</main>
<template id="field-template"><div class="field-schema__row" data-field-row><span class="field-schema__drag">⋮⋮</span><input class="admin-input" placeholder="Название" required data-name="name"><input class="admin-input" placeholder="code" pattern="[a-z][a-z0-9_]*" required data-name="code"><select class="admin-select" data-name="type"><option value="text">text</option><option value="textarea">textarea</option><option value="number">number</option><option value="boolean">boolean</option><option value="select">select</option><option value="date">date</option></select><input class="admin-input" placeholder="Опции через запятую" data-name="options"><label class="field-schema__check"><input type="hidden" value="0" data-name="required-hidden"><input type="checkbox" value="1" data-name="required"> обяз.</label><label class="field-schema__check"><input type="hidden" value="0" data-name="filterable-hidden"><input type="checkbox" value="1" data-name="filterable"> фильтр</label><button class="field-schema__remove" type="button" aria-label="Удалить поле" data-remove-field>×</button></div></template>
<script>(()=>{const container=document.getElementById('field-schema');const template=document.getElementById('field-template');const add=document.getElementById('add-field');const rename=()=>{[...container.querySelectorAll('[data-field-row]')].forEach((row,index)=>{row.querySelectorAll('[data-name]').forEach((input)=>{const key=input.dataset.name.replace('-hidden','');input.name=`fields[${index}][${key}]`;});});};add.addEventListener('click',()=>{container.append(template.content.cloneNode(true));rename();});container.addEventListener('click',(event)=>{const button=event.target.closest('[data-remove-field]');if(!button)return;button.closest('[data-field-row]').remove();rename();});rename();})();</script>
</body></html>
